import{_ as e,c as a,o as l,a4 as i}from"./chunks/framework.CyBENvPl.js";const p=JSON.parse('{"title":"前端","description":"前端技术知识库","frontmatter":{"title":"前端","showArticleMetadata":true,"sort":1,"date":"2026-05-26T00:00:00.000Z","description":"前端技术知识库"},"headers":[],"relativePath":"knowledge/frontend.md","filePath":"pages/knowledge/frontend/index.md"}'),t={name:"knowledge/frontend.md"},r=i('<h1 id="前端知识地图" tabindex="-1">前端知识地图 <a class="header-anchor" href="#前端知识地图" aria-label="Permalink to &quot;前端知识地图&quot;">​</a></h1><p>这部分按照「能落地做项目」来组织，不追求只会概念。</p><h2 id="你会在这里学到什么" tabindex="-1">你会在这里学到什么 <a class="header-anchor" href="#你会在这里学到什么" aria-label="Permalink to &quot;你会在这里学到什么&quot;">​</a></h2><ol><li>能独立完成中后台与官网类页面开发。</li><li>能搭建前端工程并接入规范、测试、发布流程。</li><li>能定位线上问题并做性能优化。</li><li>能应对大多数常见面试题与实战场景。</li></ol><h2 id="专题目录" tabindex="-1">专题目录 <a class="header-anchor" href="#专题目录" aria-label="Permalink to &quot;专题目录&quot;">​</a></h2><ol><li><a href="/knowledge/frontend/html-css">HTML/CSS</a>：页面结构、布局、响应式、动画与可访问性。</li><li><a href="/knowledge/frontend/javascript">JavaScript</a>：语言核心、异步、原型链、模块化与实战技巧。</li><li><a href="/knowledge/frontend/typescript">TypeScript</a>：类型系统、泛型、工具类型、工程配置。</li><li><a href="/knowledge/frontend/vue">Vue</a>：Vue 3 组合式 API、组件通信、状态管理与性能优化。</li><li><a href="/knowledge/frontend/react">React</a>：Hooks、状态管理、渲染机制、性能优化与架构实践。</li><li><a href="/knowledge/frontend/next-nuxt">Next/Nuxt</a>：SSR/SSG/ISR、全栈路由、部署策略。</li><li><a href="/knowledge/frontend/engineering">工程化</a>：规范、构建、测试、CI/CD、监控告警。</li></ol><h2 id="建议学习顺序" tabindex="-1">建议学习顺序 <a class="header-anchor" href="#建议学习顺序" aria-label="Permalink to &quot;建议学习顺序&quot;">​</a></h2><ol><li>HTML/CSS</li><li>JavaScript</li><li>TypeScript</li><li>Vue 或 React（二选一主线，另一条补齐）</li><li>Next/Nuxt</li><li>工程化</li></ol><h2 id="阶段目标" tabindex="-1">阶段目标 <a class="header-anchor" href="#阶段目标" aria-label="Permalink to &quot;阶段目标&quot;">​</a></h2><h3 id="阶段一-页面与交互" tabindex="-1">阶段一：页面与交互 <a class="header-anchor" href="#阶段一-页面与交互" aria-label="Permalink to &quot;阶段一：页面与交互&quot;">​</a></h3><ul><li>独立实现响应式页面。</li><li>能完成表单、列表、弹窗、上传等高频组件开发。</li></ul><h3 id="阶段二-框架与数据流" tabindex="-1">阶段二：框架与数据流 <a class="header-anchor" href="#阶段二-框架与数据流" aria-label="Permalink to &quot;阶段二：框架与数据流&quot;">​</a></h3><ul><li>能独立搭建 Vue/React 项目。</li><li>能设计组件边界、状态管理与接口层。</li></ul><h3 id="阶段三-上线与维护" tabindex="-1">阶段三：上线与维护 <a class="header-anchor" href="#阶段三-上线与维护" aria-label="Permalink to &quot;阶段三：上线与维护&quot;">​</a></h3><ul><li>能配置 lint、测试、自动化发布。</li><li>能做首屏优化、包体积优化、错误监控和性能追踪。</li></ul><h2 id="推荐项目练手" tabindex="-1">推荐项目练手 <a class="header-anchor" href="#推荐项目练手" aria-label="Permalink to &quot;推荐项目练手&quot;">​</a></h2><ol><li>管理后台（登录、权限、表格、图表、导入导出）。</li><li>内容站点（SSR、SEO、静态生成、图片优化）。</li><li>组件库（文档、单测、按需加载、版本发布）。</li></ol>',17),o=[r];function n(d,h,c,s,u,f){return l(),a("div",null,o)}const k=e(t,[["render",n]]);export{p as __pageData,k as default};
